mapper.select:
select t.apply_id,t.apply_id applyId,t.oi_id,t.oi_id oiId,t.create_user_id,t.create_user_id
createUserId,t.owner_name,t.owner_name ownerName,t.invoice_type,t.invoice_type
invoiceType,t.invoice_kind,t.invoice_kind
invoiceKind,t.invoice_name,t.invoice_name invoiceName,t.invoice_num,t.invoice_num invoiceNum,t.invoice_address,t.invoice_address invoiceAddress,
t.apply_tel,t.apply_tel applyTel,t.invoice_amount,t.invoice_amount
invoiceAmount,t.create_user_name,t.create_user_name createUserName,t.remark,t.status_cd,t.status_cd
statusCd,t.state,t.community_id,t.community_id communityId,
t.room_id,t.room_id roomId,t.room_name,t.room_name roomName,
td.`name` stateName,t.invoice_code invoiceCode,t.create_time createTime
from invoice_apply t
left join building_room br on br.room_id = t.room_id and br.status_cd = '0'
left join building_unit bu on bu.unit_id = br.unit_id and bu.status_cd = '0'
left join t_dict td on t.state = td.status_cd and td.table_name = 'invoice_apply' and td.table_columns = 'state'
where 1 =1

    and t.apply_id= #{applyId}


    and t.apply_id in

        #{applyIdItem}



    and t.oi_id != #{oiIdNotEqual}


    and t.invoice_code= #{invoiceCode}


    and t.oi_id= #{oiId}


    and t.create_user_id= #{createUserId}


    and t.owner_name= #{ownerName}


    and t.invoice_type= #{invoiceType}


    and t.invoice_kind= #{invoiceKind}


    and t.apply_tel= #{applyTel}


    and t.invoice_amount= #{invoiceAmount}


    and t.create_user_name= #{createUserName}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.room_id= #{roomId}


    and t.room_name like concat('%',#{roomNameLike},'%')


    and bu.floor_id= #{floorId}


    and bu.unit_id= #{unitId}

order by t.create_time desc

    limit #{page}, #{row}

